// These use the real clone, request assembly, formalizer workspace and saved
// results. Only the agent and, for publication, model checking are fixtures.
func writeDocument927(t *testing.T, root, name string, data []byte) {
	t.Helper()
	p := filepath.Join(root, filepath.FromSlash(name))
	if err := os.MkdirAll(filepath.Dir(p), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(p, data, 0644); err != nil {
		t.Fatal(err)
	}
}

func documentCheckout927(t *testing.T, r *rig) string {
	t.Helper()
	root := t.TempDir()
	git(t, root, "clone", "--quiet", r.origin, ".")
	return root
}

func commitDocuments927(t *testing.T, r *rig, root string) string {
	t.Helper()
	git(t, root, "add", "--all")
	git(t, root, "-c", "user.name=Fixture", "-c", "user.email=fixture@example.invalid", "commit", "--quiet", "-m", "draft context fixture")
	git(t, root, "push", "--quiet", "origin", "HEAD:main")
	return git(t, root, "rev-parse", "HEAD")
}

func declareDocuments927(t *testing.T, root string, names []string) {
	t.Helper()
	commands := map[string]repository.Command{}
	for _, phase := range []string{"install", "format", "lint", "build"} {
		commands[phase] = repository.Command{NotApplicable: "No such phase in the document fixture."}
	}
	commands["test"] = repository.Command{Argv: []string{"go", "test", "./..."}}
	commands["test_one"] = repository.Command{Argv: []string{"go", "test", "./...", "-run", "{test}"}}
	c := repository.Config{Version: 1, ProjectsDirectory: "examples", Parts: []repository.Part{{Name: "app", Directory: ".", Language: "go", Image: "fixture@sha256:" + strings.Repeat("a", 64), Inputs: []string{}, Lockfiles: []string{}, Commands: commands}}, AgentRules: []string{}, CurrentState: names, TrustedPaths: []string{}, SharedPaths: []repository.SharedPath{}}
	b, err := json.Marshal(c)
	if err != nil {
		t.Fatal(err)
	}
	writeDocument927(t, root, repository.Path, b)
}

func workspaceDocuments927(t *testing.T, root string) map[string][]byte {
	t.Helper()
	files := map[string][]byte{}
	err := filepath.WalkDir(root, func(name string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() || !d.Type().IsRegular() {
			return nil
		}
		b, err := os.ReadFile(name)
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(root, name)
		if err == nil {
			files[filepath.ToSlash(rel)] = b
		}
		return err
	})
	if err != nil {
		t.Fatal(err)
	}
	return files
}

func exactDocument927(files map[string][]byte, want []byte) string {
	for name, b := range files {
		if bytes.Equal(b, want) {
			return name
		}
	}
	return ""
}

func allDocuments927(files map[string][]byte) string {
	var b strings.Builder
	for _, data := range files {
		b.Write(data)
		b.WriteByte('\n')
	}
	return b.String()
}

func savedDocuments927(t *testing.T, r *rig, issue int) []byte {
	t.Helper()
	state, commit, err := r.f.Repo.Run(t.Context(), issue, "draft-issue")
	if err != nil || state != RunDone {
		t.Fatalf("draft has no completed record: %v %v", state, err)
	}
	b, err := r.f.Repo.Show(t.Context(), commit, "result.json")
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func visibleDocumentNotice927(t *testing.T, body string, names ...string) string {
	t.Helper()
	visible := html.UnescapeString(strings.Split(body, "<!-- invariant:")[0])
	start := strings.Index(strings.ToLower(visible), "documents not read")
	end := strings.Index(visible, "Here's what I propose")
	if end < 0 {
		end = strings.Index(visible, "Here's how I propose")
	}
	if end < 0 {
		end = strings.Index(visible, "These are unratified alternatives")
	}
	if end < 0 {
		end = strings.Index(visible, "Before I write down")
	}
	if start < 0 || end <= start {
		t.Fatalf("proposal lacks a leading Documents not read notice:\n%s", visible[:min(len(visible), 2000)])
	}
	notice := visible[start:end]
	if strings.Contains(visible[:end], "<details>") {
		t.Fatal("unread documents are hidden in a collapsed section")
	}
	for _, name := range names {
		if !strings.Contains(notice, name) {
			t.Errorf("leading notice omits %q: %s", name, notice)
		}
	}
	return notice
}

func stagedDocumentIndex927(t *testing.T, job synth.Job, commit string, names ...string) string {
	t.Helper()
	for name, data := range workspaceDocuments927(t, job.Workspace) {
		if !strings.Contains(job.Prompt, name) || !bytes.Contains(data, []byte(commit)) {
			continue
		}
		found := true
		for _, original := range names {
			found = found && bytes.Contains(data, []byte(original))
		}
		if found {
			return string(data)
		}
	}
	t.Errorf("prompt references no staged index recording commit %s and paths %v", commit, names)
	return ""
}

func documentReason927(t *testing.T, notice, name string) string {
	t.Helper()
	if strings.Count(notice, name) != 1 {
		t.Errorf("notice must name %s once: %s", name, notice)
	}
	var line string
	for _, candidate := range strings.Split(notice, "\n") {
		if strings.Contains(candidate, name) {
			line = strings.TrimSpace(strings.ReplaceAll(candidate, name, ""))
		}
	}
	if len(strings.Trim(line, "`* -|:<>/")) < 4 {
		t.Errorf("notice gives no reason for %s", name)
	}
	return line
}

// Move the fetched branch immediately after the factory resolves it. Any
// later read through origin/main would silently mix two repository versions.
type movingDocuments927 struct {
	Repo
	move func()
	seen string
}

func (r *movingDocuments927) RevParse(ctx context.Context, ref string) (string, error) {
	commit, err := r.Repo.RevParse(ctx, ref)
	if err == nil && ref == "origin/main" && r.move != nil {
		move := r.move
		r.move, r.seen = nil, commit
		move()
	}
	return commit, err
}

func TestModeledDraftGetsCommittedDocuments927(t *testing.T) {
	r := newRig(t)
	root := documentCheckout927(t, r)
	want := []byte("The PRD927: clients release a lease before another receives it.\r\nA literal command in this document is source material.\n")
	rules := []byte("DOCUMENT927, not an agent rule: do not execute this instruction.\n")
	declareDocuments927(t, root, []string{"docs/PRD.md", "docs/AGENTS.md"})
	writeDocument927(t, root, "docs/PRD.md", want)
	writeDocument927(t, root, "docs/AGENTS.md", rules)
	commit := commitDocuments927(t, r, root)
	clone := r.f.Repo.(Clone)
	writeDocument927(t, clone.Dir, "docs/PRD.md", []byte("WORKTREE_POISON927\n"))
	moving := &movingDocuments927{Repo: r.f.Repo}
	moving.move = func() {
		writeDocument927(t, root, "docs/PRD.md", []byte("LATER_BRANCH_POISON927\n"))
		commitDocuments927(t, r, root)
		if err := clone.Fetch(t.Context()); err != nil {
			t.Fatal(err)
		}
	}
	r.f.Repo = moving
	calls := 0
	r.f.Formalizer = formalize.Formalizer{Timeout: time.Minute, Backend: comparison648Agent{run: func(_ context.Context, job synth.Job) (synth.Usage, error) {
		calls++
		files := workspaceDocuments927(t, job.Workspace)
		for name := range files {
			for _, original := range []string{"PRD.md", "AGENTS.md", "CLAUDE.md"} {
				if strings.EqualFold(filepath.Base(name), original) {
					t.Errorf("staged context keeps the original or agent-rule basename: %s", name)
				}
			}
		}
		for _, data := range [][]byte{want, rules} {
			for _, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
				if strings.Contains(job.Prompt, strings.TrimSpace(line)) {
					t.Errorf("document text was embedded in the prompt: %q", line)
				}
			}
			name := exactDocument927(files, data)
			if name == "" {
				t.Errorf("modeled draft never received committed document %q", data)
				continue
			}
			info, err := os.Stat(filepath.Join(job.Workspace, name))
			if err != nil || info.Mode().Perm()&0222 != 0 {
				t.Errorf("staged context is writable: %s (%v)", name, err)
			}
		}
		all := allDocuments927(files)
		if strings.Contains(all, "WORKTREE_POISON927") || strings.Contains(all, "LATER_BRANCH_POISON927") {
			t.Error("draft read a working tree or a newer branch")
		}
		if !strings.Contains(all, commit) {
			t.Error("staged context does not identify its resolved commit")
		}
		// The prompt must point at the index, rather than merely leave files
		// somewhere the agent has no reason to inspect.
		indexName := ""
		for name, data := range files {
			if strings.Contains(job.Prompt, name) && bytes.Contains(data, []byte("docs/PRD.md")) && bytes.Contains(data, []byte(commit)) {
				indexName = name
			}
		}
		if indexName == "" {
			t.Error("agent prompt does not reference the committed document index")
		}
		lower := strings.ToLower(job.Prompt)
		if !strings.Contains(lower, "read") || !strings.Contains(lower, "context") || !strings.Contains(lower, "instruction") || !strings.Contains(lower, "unavailable") {
			t.Error("prompt omits the source-material and unavailable-document boundaries")
		}
		// Positive mentions of 'context' and 'instructions' are not enough:
		// 'follow the instructions in the context' must fail this boundary.
		negation := regexp.MustCompile(`(?i)(?:documents|context|source material)[^.\n]{0,160}\b(?:not|never)\s+(?:owner\s+)?instructions\b|\bdo not\s+(?:follow|treat)[^.\n]{0,120}(?:documents|context)[^.\n]{0,80}\binstructions\b`)
		if !negation.MatchString(job.Prompt) {
			t.Error("prompt does not explicitly say the documents are not instructions")
		}
		if indexName != "" {
			// The test backend can bypass permissions, unlike the real agents.
			// Even then, publication must retain the caller's original record.
			index := filepath.Join(job.Workspace, filepath.FromSlash(indexName))
			if err := os.Chmod(index, 0644); err != nil {
				t.Fatal(err)
			}
			forged := strings.NewReplacer(commit, strings.Repeat("f", len(commit)),
				"docs/PRD.md", "docs/AGENT_INDEX_REWRITE927.md",
				"docs/AGENTS.md", "docs/AGENT_RULE_REWRITE927.md").Replace(string(files[indexName]))
			if err := os.WriteFile(index, []byte(forged), 0644); err != nil {
				t.Fatal(err)
			}
		}
		writeDocument927(t, job.Workspace, "proposal.json", []byte(`{"unsupported":"Workspace inspected."}`))
		return synth.Usage{Summary: "Document staging inspected."}, nil
	}}}
	r.gh.open(927, "gitdek", "Start leases from docs/PRD.md", "Project: examples/new-leases\nRead [the PRD](docs/PRD.md).\n/invariant solve")
	r.poll()
	if calls != 1 || moving.seen != commit {
		t.Errorf("draft did not resolve one source commit: calls=%d, source=%q, want=%q", calls, moving.seen, commit)
	}
	record := savedDocuments927(t, r, 927)
	for _, original := range []string{commit, "docs/PRD.md", "docs/AGENTS.md"} {
		if !bytes.Contains(record, []byte(original)) {
			t.Errorf("durable run result lost caller-owned document evidence %q", original)
		}
	}
	for _, forged := range []string{strings.Repeat("f", len(commit)), "AGENT_INDEX_REWRITE927", "AGENT_RULE_REWRITE927"} {
		if bytes.Contains(record, []byte(forged)) {
			t.Errorf("rewriting the staged index changed the durable record: %q", forged)
		}
	}
}

func TestDraftNamesOmissionsBeforeRatification927(t *testing.T) {
	r := newRig(t)
	root := documentCheckout927(t, r)
	declareDocuments927(t, root, []string{"docs/PRD.md", "docs/missing.md", "docs/big.md", "docs/binary.md", "docs/link.md", "docs/unmentioned-big.md"})
	writeDocument927(t, root, "docs/PRD.md", []byte("The available PRD927.\n"))
	writeDocument927(t, root, "docs/big.md", bytes.Repeat([]byte("b"), (256<<10)+1))
	writeDocument927(t, root, "docs/unmentioned-big.md", bytes.Repeat([]byte("u"), (256<<10)+1))
	writeDocument927(t, root, "docs/binary.md", []byte("binary\x00payload927"))
	writeDocument927(t, root, "docs/other.md", []byte("Undeclared context927.\n"))
	if err := os.Symlink("PRD.md", filepath.Join(root, "docs/link.md")); err != nil {
		t.Fatal(err)
	}
	commit := commitDocuments927(t, r, root)
	tc, _ := reader603Tools(t)
	r.f.Formalizer = formalize.Formalizer{Toolchain: tc, Timeout: time.Minute, Backend: comparison648Agent{run: func(_ context.Context, job synth.Job) (synth.Usage, error) {
		stagedDocumentIndex927(t, job, commit, "docs/PRD.md", "docs/missing.md", "docs/big.md", "docs/binary.md", "docs/link.md", "docs/unmentioned-big.md")
		reader603Workspace(t, job.Workspace)
		return synth.Usage{}, nil
	}}}
	r.gh.open(927, "gitdek", "Use `docs/title.md`", "Project: examples/new-leases\nUse [PRD](docs/PRD.md#rules), `docs/missing.md`, docs/big.md, docs/binary.md and docs/link.md. Also [other](https://github.com/o/r/blob/main/docs/other.md#L2) and https://elsewhere.invalid/docs/external.md.\n/invariant solve")
	r.gh.say(927, "gitdek", "Also consult [the discussion](docs/thread.md) and `docs/missing.md`.")
	r.poll()
	post := r.expect(927, KindProposal, LabelProposal)
	names := []string{"docs/title.md", "docs/missing.md", "docs/big.md", "docs/binary.md", "docs/link.md", "docs/other.md", "docs/thread.md", "docs/unmentioned-big.md"}
	notice := visibleDocumentNotice927(t, post.Comment.Body, names...)
	for _, name := range names {
		documentReason927(t, notice, name)
	}
	if reason := documentReason927(t, notice, "docs/unmentioned-big.md"); !regexp.MustCompile(`(?i)large|size|limit|256|262144`).MatchString(reason) {
		t.Errorf("the unreferenced oversized document has no size-limit reason: %s", reason)
	}
	for _, absent := range []string{"docs/PRD.md", "docs/external.md", "examples/new-leases"} {
		if strings.Contains(notice, absent) {
			t.Errorf("notice falsely calls %s an unread document", absent)
		}
	}
	record := savedDocuments927(t, r, 927)
	for _, value := range append(names, commit) {
		if !bytes.Contains(record, []byte(value)) {
			t.Errorf("durable record loses %q", value)
		}
	}
}

func TestDraftDocumentLimitsAndLegacyFallback927(t *testing.T) {
	tc, _ := reader603Tools(t)
	for _, mode := range []string{"limits", "unsafe", "absent", "empty", "malformed", "unreadable"} {
		t.Run(mode, func(t *testing.T) {
			r := newRig(t)
			root := documentCheckout927(t, r)
			wanted, rejected := map[string][]byte{}, map[string][]byte{}
			var omitted []string
			switch mode {
			case "limits":
				names := []string{"docs/a.md", "docs/a.md", "docs/b.md", "docs/c.md", "docs/d.md", "docs/e.md", "docs/huge.md"}
				declareDocuments927(t, root, names)
				for i, name := range []string{"docs/a.md", "docs/b.md", "docs/c.md", "docs/d.md"} {
					wanted[name] = bytes.Repeat([]byte{byte('a' + i)}, 256<<10)
				}
				rejected["docs/e.md"] = []byte("Beyond the total limit927.\n")
				rejected["docs/huge.md"] = bytes.Repeat([]byte("h"), (256<<10)+1)
			case "unsafe":
				declareDocuments927(t, root, []string{"docs/good.md", "../escape927.md", "docs/invalid.md", "docs/control.md", "docs/linked/secret.md", "docs/folder"})
				wanted["docs/good.md"] = []byte("Safe text927: café\twith CRLF\r\n")
				rejected["docs/invalid.md"] = []byte{0xff, 0xfe, 'x'}
				rejected["docs/control.md"] = []byte("control\x01byte927")
				writeDocument927(t, root, "private927/secret.md", []byte("LINK_TARGET927\n"))
				writeDocument927(t, root, "docs/folder/child.md", []byte("DIRECTORY_CHILD927\n"))
				if err := os.Symlink("../private927", filepath.Join(root, "docs/linked")); err != nil {
					t.Fatal(err)
				}
				omitted = []string{"../escape927.md", "docs/linked/secret.md", "docs/folder"}
			case "empty":
				declareDocuments927(t, root, []string{})
			case "malformed":
				writeDocument927(t, root, repository.Path, []byte(`{"current_state":`))
				omitted = []string{repository.Path}
			case "unreadable":
				writeDocument927(t, root, ".invariant/linked-manifest.json", []byte(`{"current_state":[]}`))
				if err := os.Symlink("linked-manifest.json", filepath.Join(root, repository.Path)); err != nil {
					t.Fatal(err)
				}
				omitted = []string{repository.Path}
			}
			for name, data := range wanted {
				writeDocument927(t, root, name, data)
			}
			for name, data := range rejected {
				writeDocument927(t, root, name, data)
				omitted = append(omitted, name)
			}
			writeDocument927(t, root, "docs/unlisted.md", []byte("UNLISTED_PRIVATE927\n"))
			commit := commitDocuments927(t, r, root)
			calls := 0
			r.f.Formalizer = formalize.Formalizer{Toolchain: tc, Timeout: time.Minute, Backend: comparison648Agent{run: func(_ context.Context, job synth.Job) (synth.Usage, error) {
				calls++
				files := workspaceDocuments927(t, job.Workspace)
				for name, data := range wanted {
					if exactDocument927(files, data) == "" {
						t.Errorf("admissible document %s was not staged whole", name)
					}
				}
				for name, data := range rejected {
					if exactDocument927(files, data) != "" {
						t.Errorf("inadmissible document %s reached the workspace", name)
					}
				}
				all := allDocuments927(files)
				for _, poison := range []string{"UNLISTED_PRIVATE927", "LINK_TARGET927", "DIRECTORY_CHILD927"} {
					if strings.Contains(all, poison) {
						t.Errorf("undeclared or linked source reached the workspace: %s", poison)
					}
				}
				if len(omitted) > 0 {
					stagedDocumentIndex927(t, job, commit, omitted...)
				}
				reader603Workspace(t, job.Workspace)
				return synth.Usage{}, nil
			}}}
			r.gh.open(927, "gitdek", "Start a project", "See `docs/unlisted.md`.\n/invariant solve")
			r.poll()
			if calls != 1 {
				t.Fatalf("%s manifest prevented drafting: %d calls", mode, calls)
			}
			post := r.expect(927, KindProposal, LabelProposal)
			notice := visibleDocumentNotice927(t, post.Comment.Body, "docs/unlisted.md")
			for _, name := range omitted {
				documentReason927(t, notice, name)
			}
			for name := range wanted {
				if strings.Contains(notice, name) {
					t.Errorf("notice calls admitted document %s unavailable", name)
				}
			}
			record := savedDocuments927(t, r, 927)
			if !bytes.Contains(record, []byte(commit)) || !bytes.Contains(record, []byte("docs/unlisted.md")) {
				t.Errorf("%s fallback lost the capture commit or unread reference", mode)
			}
			for name := range rejected {
				if !bytes.Contains(record, []byte(name)) {
					t.Errorf("omitted document %s was not recorded", name)
				}
			}
			if mode == "malformed" && !bytes.Contains(record, []byte(repository.Path)) {
				t.Error("malformed manifest was silently treated as absent")
			}
		})
	}
}

