package synth

import (
	"encoding/json"
	"path/filepath"
	"strings"
	"testing"
)

func TestDraftReadOnlyPathsReachBothBackends927(t *testing.T) {
	ws := t.TempDir()
	contextDir := filepath.Join(ws, "context")
	job := Job{Workspace: ws, Prompt: "Read the documents and write a draft.", GateServer: []string{"invariant", "mcp", "-formalize"}, Tools: []string{"check"}}
	// Decode the intended public Job field so the base reaches the boundary
	// assertions even before it knows about per-job read-only paths.
	b, err := json.Marshal(map[string]any{"ReadOnlyPaths": []string{contextDir}})
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(b, &job); err != nil {
		t.Fatal(err)
	}
	c, _, _ := codexRig(t, codexRun)
	args, err := c.args(job, t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	var profile string
	for _, arg := range args {
		if strings.HasPrefix(arg, "permissions.invariant.filesystem=") {
			profile = arg
		}
	}
	if !strings.Contains(profile, tomlString(contextDir)+`="read"`) {
		t.Errorf("draft context has no read-only filesystem grant: %s", profile)
	}
	if !containsRun(args, []string{"-c", `permissions.invariant.extends=":workspace"`}) ||
		!strings.Contains(strings.Join(args, " "), `enabled_tools=["check"]`) {
		t.Error("document protection removed the writable drafting workspace or check tool")
	}
	claudeArgs, err := (ClaudeCode{Model: "fixture", BudgetUSD: 1, MaxTurns: 3}).args(job)
	if err != nil {
		t.Fatal(err)
	}
	flags := map[string]string{}
	for i := 0; i+1 < len(claudeArgs); i++ {
		if strings.HasPrefix(claudeArgs[i], "--") {
			flags[claudeArgs[i]] = claudeArgs[i+1]
		}
	}
	deny := flags["--disallowedTools"]
	// Claude Code absolute permission patterns begin with //; the path is
	// already absolute, so the extra slash below is intentional.
	for _, tool := range []string{"Write", "Edit"} {
		for _, path := range []string{"/" + contextDir, "/" + contextDir + "/**"} {
			if !strings.Contains(","+deny+",", ","+tool+"("+path+"),") {
				t.Errorf("draft context lacks %s denial for %s: %s", tool, path, deny)
			}
		}
	}
	if flags["--tools"] != fileTools || !strings.Contains(flags["--allowedTools"], "mcp__invariant__check") {
		t.Error("document protection removed draft file tools or the check tool")
	}
	for _, forbidden := range []string{"Bash", "WebFetch", "WebSearch", "Task", "NotebookEdit"} {
		if !strings.Contains(","+deny+",", ","+forbidden+",") {
			t.Errorf("document support removed existing %s denial", forbidden)
		}
	}
}
